// Helpers shared by the desktop and console (fullscreen) modes.

export function fileUrl(p) {
  if (!p) return null;
  const parts = p.replace(/\\/g, '/').split('/');
  return 'file:///' + parts.map((s, i) => (i === 0 && /^[A-Za-z]:$/.test(s) ? s : encodeURIComponent(s))).join('/');
}

export function mediaUrl(state, game, kind) {
  const f = game && game.media && game.media[kind];
  return f ? fileUrl(`${state.mediaDir}/${game.id}/${f}`) : null;
}

export function avatarUrl(state) {
  const a = state.settings.avatar;
  return a ? fileUrl(`${state.mediaDir}/_profile/${a}`) : null;
}

export function esc(s) {
  return String(s ?? '').replace(/[&<>"']/g, c => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' }[c]));
}

export function fmtPlaytime(sec) {
  sec = sec || 0;
  if (sec < 60) return sec ? 'Less than a minute' : 'Not played yet';
  const m = Math.round(sec / 60);
  if (m < 60) return `${m} min`;
  const h = Math.floor(m / 60);
  const r = m % 60;
  return r ? `${h}h ${r}m` : `${h}h`;
}

export function fmtHours(sec) {
  const h = (sec || 0) / 3600;
  return h < 10 ? `${Math.round(h * 10) / 10}h` : `${Math.round(h)}h`;
}

export function timeAgo(ts) {
  if (!ts) return 'Never';
  const s = Math.round((Date.now() - ts) / 1000);
  if (s < 60) return 'Just now';
  const m = Math.round(s / 60);
  if (m < 60) return `${m} min ago`;
  const h = Math.round(m / 60);
  if (h < 24) return `${h} hr${h > 1 ? 's' : ''} ago`;
  const d = Math.round(h / 24);
  if (d < 30) return `${d} day${d > 1 ? 's' : ''} ago`;
  return new Date(ts).toLocaleDateString(undefined, { year: 'numeric', month: 'short', day: 'numeric' });
}

export const SOURCES = {
  steam: 'Steam',
  epic: 'Epic Games',
  gog: 'GOG',
  manual: 'PC',
};

export const SORTS = {
  recent: { label: 'Recently Played', fn: (a, b) => (b.lastPlayed || 0) - (a.lastPlayed || 0) || b.added - a.added },
  name: { label: 'Name', fn: (a, b) => a.name.localeCompare(b.name, undefined, { sensitivity: 'base', numeric: true }) },
  playtime: { label: 'Play Time', fn: (a, b) => (b.playtime || 0) - (a.playtime || 0) },
  added: { label: 'Recently Added', fn: (a, b) => b.added - a.added },
};

