export function icon(name, cls = '') {
  return `<svg class="ico ${cls}" viewBox="0 0 256 256" fill="currentColor" aria-hidden="true">${P[name] || ''}</svg>`;
}

// Font files dropped in assets/fonts (meant for Sony's SST) become the UI font "PC4 Custom".
export async function loadCustomFonts(state) {
  const list = (state && state.fonts) || [];
  if (!list.length || !document.fonts) return false;
  await Promise.all(list.map(f => new FontFace('PC4 Custom', `url("${fileUrl(f.file)}")`, { weight: String(f.weight), style: f.style })
    .load().then(face => document.fonts.add(face)).catch(() => {})));
  return true;
}

// A user's zoom/position for one image (game.artAdjust[kind]); applied on top of the original, never baked in.
export function adjustTransform(a) {
  return a ? `translate(${a.x || 0}%,${a.y || 0}%) scale(${a.z || 1})` : '';
}

// Pictures pan inside their frame (object-position) and zoom around that point, so a filled frame never shows gaps.
// x/y run from -100 to 100: positive moves the picture right/down.
const panPos = a => `${50 - (a.x || 0) / 2}% ${50 - (a.y || 0) / 2}%`;

export function adjustStyle(a) {
  return a ? `object-fit:${a.fit || 'cover'};object-position:${panPos(a)};transform-origin:${panPos(a)};transform:scale(${a.z || 1});` : '';
}

// the same for a full-screen background-image element
export function adjustBackground(el, a) {
  el.style.backgroundPosition = a ? panPos(a) : '';
  el.style.transformOrigin = a ? panPos(a) : '';
  el.style.transform = a ? `scale(${a.z || 1})` : '';
}

// ---- controller support: icons + what the game supports ----
// Outlines from open icon sets, so they sit with PC4's other line icons:
// DUALSHOCK 4 = iconoir "playstation-gamepad" (MIT), Xbox = Fluent UI "xbox-controller-24-regular" (MIT),
// keyboard = Fluent UI "keyboard-mouse-20-regular" (MIT). The white DualSense is filled from the iconoir outline.
// the controllers themselves: Kenney's silhouettes (DUALSHOCK 4, DualSense, Xbox Series); keyboard: Phosphor
const ctlSvg = (name, dy = 0) => `<svg class="ctl-ico" viewBox="0 ${-dy} 256 256" fill="currentColor">${P[name]}</svg>`; // dy: centres the pad vertically
const CTL_ICONS = { ps4: ctlSvg('ps4', 48), ps5: ctlSvg('ps5', 44), xbox: ctlSvg('xbox', 40), keyboard: ctlSvg('keyboard') };
CTL_ICONS.playstation = CTL_ICONS.ps4;

export function controllerIcon(kind) { return CTL_ICONS[kind] || ''; }

// a small controller silhouette for the status bar (centred in a short box)
// vertical centre of each controller drawing (measured with getBBox): the 180-high view box is centred on it,
// so the whole controller shows (shoulder buttons too) and it sits on the same line as the other icons
const PAD_CY = { ps4: 79.5, ps5: 84.3, xbox: 87.8 };
export function padGlyph(kind) {
  const k = PAD_CY[kind] ? kind : 'ps4';
  return `<svg class="ico pad-glyph" viewBox="0 ${(PAD_CY[k] - 90).toFixed(1)} 256 180" fill="currentColor">${P[k]}</svg>`;
}

// Which button layout a controller has, from its browser id
// ("DualSense Wireless Controller (STANDARD GAMEPAD Vendor: 054c Product: 0ce6)", "Xbox 360 Controller (XInput STANDARD GAMEPAD)")
export function padFamily(id) {
  id = (id || '').toLowerCase();
  if (!id) return null;
  if (/dualsense|054c.*\b(0ce6|0df2|0e5f)\b/.test(id)) return 'ps5';
  if (/054c|wireless controller|dualshock|playstation/.test(id)) return 'ps4';
  return 'xbox'; // XInput pads and everything else use the Xbox layout
}

// with Xbox emulation on, the virtual Xbox pad shows up next to the real one: the PlayStation pad wins
const firstPad = () => { const l = navigator.getGamepads ? [...navigator.getGamepads()].filter(Boolean) : []; return l.find(p => /054c/i.test(p.id)) || l[0]; };
let lastFamily = null; // remembered, so the icons don't flip back when a controller goes to sleep

// the button icons to show: the user's choice, or the controller plugged in (settings.padIcons = 'auto')
export function padStyle(settings) {
  const pad = firstPad();
  if (pad) lastFamily = padFamily(pad.id);
  const pick = settings && settings.padIcons;
  if (pick && pick !== 'auto') return pick;
  return lastFamily || 'ps4';
}

// What kind of controller is plugged in right now: 'playstation' | 'xbox' | 'other' | null
export function connectedPad() {
  const pad = firstPad();
  if (!pad) return null;
  const f = padFamily(pad.id);
  if (f === 'ps4' || f === 'ps5') return 'playstation';
  return /045e|xbox|xinput/i.test(pad.id) ? 'xbox' : 'other';
}

// How well a game plays with each kind of input, from its Steam controller categories
export function controllerSupport(g) {
  const c = g.meta && g.meta.controllers;
  if (!c || !c.checked) return { known: false, playstation: null, xbox: null, keyboard: 'yes' };
  const nativePs = c.dualshock || c.dualsense;
  return {
    known: true,
    playstation: nativePs ? 'native' : c.xbox ? 'emulated' : 'no',
    xbox: c.xbox || 'no',
    keyboard: 'yes',
    dualsense: c.dualsense,
  };
}

// one plain sentence for the person holding `pad`
export function controllerAdvice(g, pad) {
  const s = controllerSupport(g);
  if (!s.known) return "PC4 doesn't know this game's controller support (it isn't linked to Steam). Keyboard and mouse always work.";
  const steam = g.source === 'steam';
  if (pad === 'playstation') {
    if (s.playstation === 'native') return `Your PlayStation controller works natively${s.dualsense ? ', including DualSense features' : ''}, with ✕ ○ △ □ button icons.`;
    if (s.playstation === 'emulated') return steam
      ? 'Plays with your PlayStation controller through Xbox controller emulation. Steam Input does this for you automatically.'
      : 'Plays with your PlayStation controller through Xbox controller emulation: turn on Steam Input, or run DS4Windows.';
    return 'This game is made for keyboard and mouse.';
  }
  if (pad === 'xbox') return s.xbox === 'no' ? 'This game is made for keyboard and mouse.' : `Your Xbox controller is ${s.xbox === 'full' ? 'fully' : 'partly'} supported.`;
  if (s.playstation === 'native') return 'Works natively with PlayStation controllers, Xbox controllers and keyboard.';
  if (s.xbox !== 'no') return 'Made for Xbox controllers. A PlayStation controller works through emulation (Steam Input or DS4Windows).';
  return 'This game is made for keyboard and mouse.';
}

export const SUPPORT_LABEL = { native: 'Native', emulated: 'Via Xbox emulation', full: 'Full support', partial: 'Partial support', yes: 'Supported', no: 'Not supported' };
